      "te": "యోగాన్ని పొందాలనుకునే ఋషికి, చర్యే సాధనంగా చెప్పబడింది; యోగాన్ని పొందిన అదే జ్ఞాని కోసం, నిష్క్రియాత్మకత సాధనంగా చెప్పబడింది.",
      "hi": "जो योग-(समता-) में आरूढ़ होना चाहता है, ऐसे मननशील योगीके लिये कर्तव्य-कर्म करना कारण कहा गया है और उसी योगारूढ़ मनुष्यका शम (शान्ति) परमात्मप्राप्तिमें कारण कहा गया है।",
      "sa": "आरुरुक्षोर्मुनेर्योगं कर्म कारणमुच्यते।\n\nयोगारूढस्य तस्यैव शमः कारणमुच्यते।।6.3।।",
      "gu": "આ શ્લોકમાં ‘આરૂરુક્ષુ’ — એટલે કે યોગ પ્રાપ્ત કરવાની ઇચ્છા ધરાવતા મુનિ — માટે કર્મ, એટલે નિષ્કામ કર્તવ્યકર્મ કરવું કારણરૂપ ગણાયું છે. તેનો અર્થ છે કે યોગ સુધી પહોંચવાનો પ્રથમ પગથિયો કર્મ છે, કારણ કે કર્મ મનને શુદ્ધ કરે છે અને તેને યોગ માટે તૈયાર બનાવે છે.",
