      "te": "మనస్సును జయించిన వానికి ఆ మనస్సే మిత్రుడు; మనస్సును జయించని వానికి ఆ మనస్సే శత్రువులా ప్రవర్తిస్తుంది.",
      "hi": "जिसने अपने-आपसे अपने-आपको जीत लिया है, उसके लिये आप ही अपना बन्धु है और जिसने अपने-आपको नहीं जीता है, ऐसे अनात्माका आत्मा ही शत्रुतामें शत्रुकी तरह बर्ताव करता है।",
      "sa": "बन्धुरात्माऽऽत्मनस्तस्य येनात्मैवात्मना जितः।\n\nअनात्मनस्तु शत्रुत्वे वर्तेतात्मैव शत्रुवत्।।6.6।।",
      "gu": "'જેન આત્મૈવ આત્મના જીતઃ' એનો અર્થ છે કે જેને પોતાનો મન, ઇન્દ્રિયો અને શરીર પર વિજય મેળવ્યો છે, એ પોતાના માટે પોતે જ મિત્ર બની જાય છે. જે વ્યક્તિ પોતાની અંદર રહેલા દુર્ગુણો અને વૃત્તિઓ પર કાબૂ મેળવે છે, તેને આત્મસંયમ પ્રાપ્ત થાય છે.",
      "ta": null,
      "kn": null,
      "ml": null,
      "mr": null,
      "bn": null,
      "pa": null,
