      "te": "ఇంద్రియాలను జయించిన జ్ఞానము మరియు జ్ఞానముతో తృప్తి చెందిన యోగి, ఎవరికి ఒక మట్టిముద్ద, ఒక రాయి, బంగారం అన్నీ ఒకే విధంగా ఉంటాయి, అతను నిర్వికల్ప సమాధిని పొందాడని చెప్పబడింది.",
      "hi": "जिसका अन्तःकरण ज्ञान-विज्ञानसे तृप्त है, जो कूटकी तरह निर्विकार है, जितेन्द्रिय है और मिट्टीके ढेले, पत्थर तथा स्वर्णमें समबुद्धिवाला है -- ऐसा योगी युक्त (योगारूढ़) कहा जाता है।",
      "sa": "ज्ञानविज्ञानतृप्तात्मा कूटस्थो विजितेन्द्रियः।\n\nयुक्त इत्युच्यते योगी समलोष्टाश्मकाञ्चनः।।6.8।।",
      "gu": "જ્ઞાન અને વિજ્ઞાન એ બે ગુણો છે જે યોગીને તૃપ્તિ આપે છે. જ્ઞાનથી અર્થ થાય છે નિર્વિકાર બ્રહ્મનું જ્ઞાન અને વિજ્ઞાનથી અર્થ થાય છે દૈવી પ્રકૃતિનું અનુભવજન્ય જ્ઞાન.",
      "ta": null,
      "kn": null,
      "ml": null,
      "mr": null,
      "bn": null,
      "pa": null,
      "or": null,
      "as": null,
      "ur": null,
      "ks": null,
      "kok": null,
      "mai": null,
      "mni": null,
      "ne": null,
      "brx": null,
      "sat": null,
