    "teluguMeaning": "ఒక పరిశుభ్రమైన ప్రదేశంలో, ఒకదానిపై ఒకటి పొరలుగా ఉన్న వస్త్రం, చర్మం మరియు కుశ గడ్డితో తయారు చేయబడిన, చాలా ఎత్తుగా లేదా చాలా తక్కువగా ఉండకుండా, తన స్వంత స్థిరమైన ఆసనాన్ని ఏర్పాటు చేసుకున్నాడు.",
    "iast": "śhuchau deśhe pratiṣhṭhāpya sthiram āsanam ātmanaḥ\nnātyuchchhritaṁ nāti-nīchaṁ chailājina-kuśhottaram",
    "translations": {
      "en": "In a clean spot, having established a firm seat of his own, neither too high nor too low, made of cloth, skin, and kusha grass layered one over the other.",
      "te": "ఒక పరిశుభ్రమైన ప్రదేశంలో, ఒకదానిపై ఒకటి పొరలుగా ఉన్న వస్త్రం, చర్మం మరియు కుశ గడ్డితో తయారు చేయబడిన, చాలా ఎత్తుగా లేదా చాలా తక్కువగా ఉండకుండా, తన స్వంత స్థిరమైన ఆసనాన్ని ఏర్పాటు చేసుకున్నాడు.",
      "hi": "शुद्ध भूमिपर, जिसपर क्रमशः कुश, मृगछाला और वस्त्र बिछे हैं, जो न अत्यन्त ऊँचा है और न अत्यन्त नीचा, ऐसे अपने आसनको स्थिरस्थापन करके।",
      "sa": "शुचौ देशे प्रतिष्ठाप्य स्थिरमासनमात्मनः।\n\nनात्युच्छ्रितं नातिनीचं चैलाजिनकुशोत्तरम्।।6.11।।",
      "gu": "આ શ્લોકમાં આસન બનાવવામાં કુશ ઘાસ, મૃગછાલ અને કપડાંનો ઉપયોગ કરવાની સલાહ આપવામાં આવી છે. આ ત્રણેય વસ્તુઓ આસનને શુદ્ધ અને આરામદાયક બનાવે છે. કુશ ઘાસ આધ્યાત્મિક શુદ્ધિ માટે મહત્વપૂર્ણ છે, જ્યારે મૃગછાલ સ્થિરતા અને કપડું આરામ માટે છે.",
      "ta": null,
      "kn": null,
      "ml": null,
      "mr": null,
      "bn": null,
      "pa": null,
      "or": null,
      "as": null,
      "ur": null,
      "ks": null,
      "kok": null,
      "mai": null,
      "mni": null,
      "ne": null,
      "brx": null,
      "sat": null,
      "sd": null,
      "doi": null
    },
    "hindiMeaning": "शुद्ध भूमिपर, जिसपर क्रमशः कुश, मृगछाला और वस्त्र बिछे हैं, जो न अत्यन्त ऊँचा है और न अत्यन्त नीचा, ऐसे अपने आसनको स्थिरस्थापन करके।",
    "englishTranslation": "In a clean spot, having established a firm seat of his own, neither too high nor too low, made of cloth, skin, and kusha grass layered one over the other."
