      "te": "అక్కడ, మనస్సు మరియు ఇంద్రియాలను నియంత్రించే చర్యలతో, మనస్సును ఏకబిందువుగా చేసి, ఆసనంపై కూర్చొని, స్వీయ శుద్ధి కోసం యోగాను అభ్యసించనివ్వండి.",
      "hi": "उस आसनपर बैठकर चित्त और इन्द्रियोंकी क्रियाओंको वशमें रखते हुए मनको एकाग्र करके अन्तःकरणकी शुद्धिके लिये योगका अभ्यास करे।",
