      "gu": "મનને એકાગ્ર બનાવવા માટે આ શ્લોકમાં સુપરીચિત આસન પર બેસવું, અને પછી મન તથા ઇન્દ્રિયો ઉપર નિયંત્રણ રાખવું કહેવામાં આવ્યું છે. આ રીતે, મનની ચંચળતા દૂર કરીને ધ્યાન કેન્દ્રિત કરવાનું છે.",
