      "te": "నిర్మలమైన మనస్సుగల, నిర్భయమైన, బ్రహ్మచారి యొక్క ప్రతిజ్ఞలో దృఢంగా, వారి మనస్సును నియంత్రించి, నా గురించి ఆలోచించి మరియు మనస్సులో సమతుల్యతను కలిగి ఉండి, నన్ను తమ పరమ లక్ష్యంగా పెట్టుకుని కూర్చోనివ్వండి.",
