      "te": "ఈ విధంగా, ఎల్లప్పుడూ మనస్సును సమతుల్యంగా ఉంచుతూ, యోగి, మనస్సును అదుపులో ఉంచుకుని, నాలో స్థిరంగా ఉండే శాంతిని పొందుతాడు, ముక్తిలో ముగుస్తుంది.",
      "hi": "नियत  मनवाला योगी मनको इस तरहसे सदा परमात्मामें लगाता हुआ मेरेमें सम्यक् स्थितिवाली जो निर्वाणपरमा शान्ति है, उसको प्राप्त हो जाता है।",
      "sa": "युञ्जन्नेवं सदाऽऽत्मानं योगी नियतमानसः।\n\nशान्तिं निर्वाणपरमां मत्संस्थामधिगच्छति।।6.15।।",
      "gu": "અનુશાસિત મનનો યોગી સતત પોતાના મનને ભગવાનમાં લગાવીને પરમાનંદ રૂપ શાંતિ પ્રાપ્ત કરે છે. આ શાંતિ શાશ્વત છે અને ભગવાનમાં સ્થિત છે. યોગીનું મન જ્યારે સતત ભગવાનમાં લીન રહે છે તો તેને આ શાંતિ પ્રાપ્ત થાય છે.",
