      "en": "Let this be known by the name of Yoga, the severance from union with pain. This Yoga should be practiced with determination and with an undespairing mind.",
      "te": "దీనిని యోగ అనే పేరుతో తెలియచేయండి, నొప్పితో కలయిక నుండి విడదీయడం. ఈ యోగాన్ని దృఢ సంకల్పంతో, నిస్పృహలేని మనస్సుతో సాధన చేయాలి.",
      "hi": "जिसमें दुःखोंके संयोगका ही वियोग है, उसीको 'योग' नामसे जानना चाहिये। (वह योग जिस ध्यानयोगका लक्ष्य है,) उस ध्यानयोगका अभ्यास न उकताये हुए चित्तसे निश्चयपूर्वक करना चाहिये।",
      "sa": "तं विद्याद् दुःखसंयोगवियोगं योगसंज्ञितम्।\n\nस निश्चयेन योक्तव्यो योगोऽनिर्विण्णचेतसा।।6.23।।",
      "gu": "આ શ્લોકમાં તે યોગને “રાજયોગ” કહેવાયો છે જે મનુષ્યને દુઃખના તમામ સંયોગોથી સંપૂર્ણ મુક્તિ આપે છે. આ યોગ દ્વારા પ્રાપ્ત થતી અવસ્થા સર્વોત્તમ અને સ્થિર સુખરૂપ છે. જે વ્યક્તિ આ યોગમાં સ્થિર થાય છે તે ફરીથી દુઃખમાં બંધાતો નથી અને પરમશાંતિ પ્રાપ્ત કરે છે.",
      "ta": null,
      "kn": null,
      "ml": null,
      "mr": null,
      "bn": null,
      "pa": null,
      "or": null,
      "as": null,
      "ur": null,
      "ks": null,
