    "teluguMeaning": "సంకల్ప (ఆలోచన మరియు ఊహ) ద్వారా పుట్టిన కోరికలన్నింటినీ నిర్విరామంగా త్యజించడం మరియు అన్ని వైపుల నుండి మనస్సు ద్వారా మొత్తం ఇంద్రియాల సమూహాన్ని పూర్తిగా నిరోధించడం.",
