      "te": "సంకల్ప (ఆలోచన మరియు ఊహ) ద్వారా పుట్టిన కోరికలన్నింటినీ నిర్విరామంగా త్యజించడం మరియు అన్ని వైపుల నుండి మనస్సు ద్వారా మొత్తం ఇంద్రియాల సమూహాన్ని పూర్తిగా నిరోధించడం.",
      "hi": "संकल्पसे उत्पन्न होनेवाली सम्पूर्ण कामनाओंका सर्वथा त्याग करके और मनसे ही इन्द्रिय-समूहको सभी ओरसे हटाकर।",
