      "te": "ఎవరైతే, ఐక్యతతో స్థిరపడి, అన్ని జీవులలో నివసించే నన్ను ఆరాధిస్తారో, ఆ యోగి వారి జీవన విధానం ఏదైనప్పటికీ నాలో ఉంటాడు.",
      "hi": "मेरेमें एकीभावसे स्थित हुआ जो योगी सम्पूर्ण प्राणियोंमें स्थित मेरा भजन करता है, वह सब कुछ बर्ताव करता हुआ भी मेरेमें ही बर्ताव कर रहा है अर्थात् वह सर्वथा मेरेमें ही स्थित है।",
      "sa": "सर्वभूतस्थितं यो मां भजत्येकत्वमास्थितः।\n\nसर्वथा वर्तमानोऽपि स योगी मयि वर्तते।।6.31।।",
