      "gu": "‘સમં પશ્વતિ’નો અર્થ છે — દરેક જીવોને સમાન દૃષ્ટિથી જોવું. યોગી માટે બધા જીવ એકસરખા હોય છે; તે તેમના સુખ અને દુઃખને સમાન રીતે અનુભવે છે. તેનું હૃદય સર્વ પ્રાણીઓ પ્રત્યે સમાન પ્રેમ અને કરુણાથી ભરેલું હોય છે, એટલે તે કોઈ પ્રત્યે પક્ષપાત કે દ્વેષ રાખતો નથી.",
