    "teluguTranslation": "శ్రీ భగవానుడు పలికెను: ఓ మహాబాహూ! మనస్సు చంచలమైనది, నిగ్రహించడం కష్టమన్నది నిజమే. అయినప్పటికీ నిరంతర అభ్యాసము మరియు వైరాగ్యములతో దానిని వశపరచుకోవచ్చు.",
    "teluguExplanation": "అధ్యాయం 6 (ఆత్మ సంయమ యోగము), శ్లోకం 35 ద్వారా శ్రీ భగవానుడు ప్రబోధించిన దివ్య సందేశం:\nఈ శ్లోకము మన అంతఃకరణ శుద్ధికి, కర్తవ్య నిర్వహణకు మరియు అంతర్గత శాంతికి మార్గదర్శనం చేస్తుంది. ధ్యాన యోగము, మనస్సును నిగ్రహించే విధానము మరియు అభ్యాస-వైరాగ్యములు. భగవద్గీత బోధనలను మన నిత్య జీవితంలో ఆచరించడం ద్వారా పరమ శాంతిని, మోక్షాన్ని పొందవచ్చు.",
    "practicalApplication": "Reflect on the sacred principle of Chapter 6, Verse 35: apply integrity, focus on duty without anxiety over outcomes, and cultivate inner peace.",
    "practicalApplicationTelugu": "ఆచరణ: నిరంతర సాధన (అభ్యాసము) మరియు వైరాగ్యం ద్వారా చంచలమైన మనస్సును అదుపులో ఉంచుకోవచ్చు. ప్రతి పనిని సత్సంకల్పంతో, భగవదర్పణ భావంతో ఆచరించండి.",
