      "te": "అర్జునుడు ఇలా అన్నాడు, \"తనకు విశ్వాసం ఉన్నప్పటికీ, తనను తాను నియంత్రించుకోలేనివాడు మరియు ఎవరి మనస్సు యోగా నుండి దూరంగా తిరుగుతుందో, అతను యోగాలో పరిపూర్ణతను పొందలేకపోయాడు, ఓ కృష్ణా?\"",
      "hi": "अर्जुन बोले - हे कृष्ण ! जिसकी साधनमें श्रद्धा है, पर जिसका प्रयत्न शिथिल है, वह अन्तसमयमें अगर योगसे विचलितमना हो जाय, तो वह योगसिद्धिको प्राप्त न करके किस गतिको चला जाता है?",
      "sa": "अर्जुन उवाच\n\nअयतिः श्रद्धयोपेतो योगाच्चलितमानसः।\n\nअप्राप्य योगसंसिद्धिं कां गतिं कृष्ण गच्छति।।6.37।।",
      "gu": "અર્જુન કૃષ્ણને પૂછે છે કે જે વ્યક્તિ શ્રદ્ધાવાન હોવા છતાં મનને વશમાં રાખવામાં નિષ્ફળ જાય છે અને યોગથી વિખૂટો પડે છે, તેને આગળ શું ફળ મળે છે? શું તે યોગસિદ્ધિ પ્રાપ્ત કર્યા વગર અધોગતિ પામે છે કે તેની આધ્યાત્મિક યાત્રા વ્યર્થ જાય છે? અર્જુન જાણવા માંગે છે કે આવા યોગભ્રષ્ટ વ્યક્તિની ગતિ શું થાય છે.",
