      "te": "ఓ కృష్ణా, దయచేసి నా ఈ సందేహాన్ని పూర్తిగా నివృత్తి చేయండి, అలా చేయడం నీకు తప్ప ఎవరికీ సాధ్యం కాదు.",
      "hi": "हे कृष्ण! मेरे इस सन्देहका सर्वथा छेदन करनेके लिये आप ही योग्य हैं; क्योंकि इस संशयका छेदन करनेवाला आपके सिवाय दूसरा कोई हो नहीं सकता।",
      "sa": "एतन्मे संशयं कृष्ण छेत्तुमर्हस्यशेषतः।\n\nत्वदन्यः संशयस्यास्य छेत्ता न ह्युपपद्यते।।6.39।।",
      "gu": "અર્જુન તેના મનમાં ઉપજેલા સંશયને સમાપ્ત કરવા માટે કૃષ્ણને વિનંતી કરે છે.",
      "ta": null,
      "kn": null,
      "ml": null,
