      "gu": "આ શ્લોકમાં એવા લોકોની વાત છે જ્યાં યોગભ્રષ્ટ વ્યક્તિ જાય છે, જે પુણ્યકર્મ કરનારા છે. આ લોકો ધર્મ અને સદ્ગુણોથી ભરપૂર છે.",
