      "te": "అదే పూర్వ అభ్యాసం ద్వారా, అతను తనకు తానుగా ఉన్నప్పటికీ భరించబడ్డాడు. కేవలం యోగాన్ని తెలుసుకోవాలనుకునేవాడు కూడా బ్రాహ్మణ పదానికి అతీతంగా ఉంటాడు.",
      "hi": "वह (श्रीमानोंके घरमें जन्म लेनेवाला योगभ्रष्ट मनुष्य) भोगोंके परवश होता हुआ भी पूर्वजन्ममें किये हुए अभ्यास-(साधन-) के कारण ही परमात्माकी तरफ खिंच जाता है; क्योंकि योग-(समता-) का जिज्ञासु भी वेदोंमें कहे हुए सकाम कर्मोंका अतिक्रमण कर जाता है।",
      "sa": "पूर्वाभ्यासेन तेनैव ह्रियते ह्यवशोऽपि सः।\n\nजिज्ञासुरपि योगस्य शब्दब्रह्मातिवर्तते।।6.44।।",
      "gu": "તે વ્યક્તિને તેના પૂર્વ જન્મના અભ્યાસના કારણે ભગવાન તરફ આકર્ષણ થાય છે. આ ભ્રષ્ટ યોગી, શ્રીમાનોના ઘરમાં જન્મ લઈને પણ, તેના ઇન્દ્રિયોના વશમાં હોવા છતાં ભગવાનની તરફેણમાં ખેંચાય છે.",
