    "hindiMeaning": "वह (श्रीमानोंके घरमें जन्म लेनेवाला योगभ्रष्ट मनुष्य) भोगोंके परवश होता हुआ भी पूर्वजन्ममें किये हुए अभ्यास-(साधन-) के कारण ही परमात्माकी तरफ खिंच जाता है; क्योंकि योग-(समता-) का जिज्ञासु भी वेदोंमें कहे हुए सकाम कर्मोंका अतिक्रमण कर जाता है।",
